negativeExample:
public class Example {
    public void testMethod(Object o) {
        // This case has a `null` fallback, so the null check is necessary.
        java.lang.String proposal = (o instanceof java.lang.String) ? (java.lang.String) o : null;
        if (proposal == null)
            proposal = "default"; // This line must remain
        System.out.println(proposal);
    }
}
